import os


def get_foundry_config() -> dict:
    return {
        "endpoint": os.getenv("FOUNDRY_AGENT_ENDPOINT", ""),
        "api_key": os.getenv("FOUNDRY_API_KEY", ""),
        "agent_id": os.getenv("FOUNDRY_AGENT_ID", ""),
    }

import requests


def ask_agent(config: dict, prompt: str) -> dict:
    url = f"{config['endpoint'].rstrip('/')}/{config['agent_id']}/invoke"
    headers = {
        "Content-Type": "application/json",
        "x-api-key": config["api_key"],
    }
    response = requests.post(url, headers=headers, json={"input": prompt}, timeout=30)
    response.raise_for_status()
    return response.json()
